// Cyrus R4 worldgen: the VERSION-NEUTRAL resource kinds the build model may write into a DataPackSpec (still
// schemaVersion 1: the new kinds are additions to the resource union, so every existing v1 spec stays valid and emits
// the same bytes). World generation is confined to the mod's OWN namespace: a custom dimension (dimension +
// dimension_type) whose biome source uses only the pack's own biomes, the pack's own features in those biomes, and
// structures placed only in those biomes. Vanilla biomes / dimensions / noise are never edited (see NOT_SUPPORTED).
//
// Engine safety: there is no custom noise router or density function: terrain shape comes from a vanilla
// noise_settings PRESET, so an absurd generator cannot be written. Every count / size below is capped
// (WORLDGEN_LIMITS), and ./cost.ts turns a pack into a per-chunk cost estimate with a hard ceiling.
import { z } from "zod";

export const WORLDGEN_LIMITS = {
  dimensions: 2, dimensionTypes: 2, biomes: 16, configuredFeatures: 32, placedFeatures: 32, templates: 8, structures: 8, structureSets: 4,
  /** own + vanilla placed features per biome */
  featuresPerBiome: 24,
  spawnsPerBiome: 16,
  /** structure template: each side <= 48 blocks (max volume 48 x 48 x 48), non-void blocks <= 32768, palette <= 32 */
  templateSide: 48, templateBlocks: 32768, paletteSize: 32, lootBlocksPerTemplate: 16,
  /** feature placement attempts per chunk (count x patch tries) per placed feature / per biome */
  attemptsPerFeature: 256, attemptsPerBiome: 1024,
  /** per-chunk cost estimate ceiling (cost.ts units); above it the pack is refused */
  maxCost: 100,
} as const;

const PATH = /^[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/;
const REF = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const Path = z.string().max(64).regex(PATH, "lowercase letters, digits, _ and / (max 6 segments)");
const Ref = z.string().max(120).regex(REF, "a namespaced id like minecraft:stone or nx_abcd1234:my_biome");
const IdRef = z.string().max(120).regex(/^[a-z0-9_.-]+:[a-z0-9_./-]+$/, "a namespaced id (no #tag here)");
const Int = (min: number, max: number) => z.number().int().min(min).max(max);
const Hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, "a colour like #7ba4ff");
const PropName = z.string().regex(/^[a-z0-9_]{1,32}$/);
const PropValue = z.string().regex(/^[a-z0-9_]{1,32}$/);

/** A block state: a vanilla block id + optional properties (checked against the version's real block state table). */
export const BlockStateSchema = z.strictObject({ block: IdRef, properties: z.record(PropName, PropValue).optional() });
export type DpBlockState = z.infer<typeof BlockStateSchema>;
